import type { JSX, SVGProps } from "react";

export type StarIconProps = Omit<SVGProps<SVGSVGElement>, "color"> & {
  size?: number;
  color?: string;
  testID?: string;
};

/**
 * Lucide `Star` for the web and for the DOM-based tests. The native twin is
 * `Star.native.tsx`, generated by the official Tamagui v3 command
 * (`npx @tamagui/cli icons add Star`) on top of `react-native-svg`.
 */
export function Star({
  size = 24,
  color = "currentColor",
  testID,
  ...rest
}: StarIconProps): JSX.Element {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke={color}
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
      {...rest}
      aria-hidden="true"
      focusable="false"
      data-testid={testID}
    >
      <polygon
        points="12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2"
        stroke={color}
      />
    </svg>
  );
}

Star.displayName = "Star";
